const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometry (JFK Airport)
  const jfk = ee.Geometry.Point([-73.7781, 40.6413]);

  // 2. Function to get daily max temperature for a specific date
  async function getDailyMaxTemp(dateStr) {
    const date = ee.Date(dateStr);
    const nextDay = date.advance(1, 'day');

    const collection = ee.ImageCollection('ECMWF/ERA5_LAND/HOURLY')
      .filterDate(date, nextDay)
      .select('temperature_2m');

    const count = collection.size().getInfo();
    console.log(`${dateStr} Images: ${count}`);

    if (count === 0) {
      return {temp: null, validPixels: 0};
    }

    // Convert K to C and get daily max
    const dailyMax = collection.map(img => img.subtract(273.15))
      .max();

    // Check valid pixels
    const pixelCount = dailyMax.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: jfk,
      scale: 1000,
      maxPixels: 1e9
    }).get('temperature_2m').getInfo();

    if (pixelCount === 0) {
      return {temp: null, validPixels: 0};
    }

    // Get temperature value
    const temp = dailyMax.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: jfk,
      scale: 1000,
      maxPixels: 1e9
    }).get('temperature_2m').getInfo();

    return {temp: temp, validPixels: pixelCount};
  }

  // 3. Function to get max June temperature for a specific year
  async function getJuneMaxTemp(year) {
    const juneStart = ee.Date(`${year}-06-01`);
    const julyStart = ee.Date(`${year}-07-01`);

    const collection = ee.ImageCollection('ECMWF/ERA5_LAND/HOURLY')
      .filterDate(juneStart, julyStart)
      .select('temperature_2m');

    const count = collection.size().getInfo();
    console.log(`June ${year} Images: ${count}`);

    if (count === 0) {
      return {temp: null, validPixels: 0};
    }

    // Convert K to C and get max over all hours in June
    const juneMax = collection.map(img => img.subtract(273.15))
      .max();

    // Check valid pixels
    const pixelCount = juneMax.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: jfk,
      scale: 1000,
      maxPixels: 1e9
    }).get('temperature_2m').getInfo();

    if (pixelCount === 0) {
      return {temp: null, validPixels: 0};
    }

    // Get temperature value
    const temp = juneMax.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: jfk,
      scale: 1000,
      maxPixels: 1e9
    }).get('temperature_2m').getInfo();

    return {temp: temp, validPixels: pixelCount};
  }

  // 4. Get temperature for June 24, 2025
  console.log("Getting temperature for June 24, 2025...");
  const temp2025 = await getDailyMaxTemp('2025-06-24');

  if (temp2025.temp === null) {
    if (temp2025.validPixels === 0) {
      console.log("C2: No valid pixels for 2025-06-24");
      console.log("<answer>C2</answer>");
    } else {
      console.log("C1: No data for 2025-06-24");
      console.log("<answer>C1</answer>");
    }
    return;
  }

  console.log(`2025-06-24 Temp: ${temp2025.temp.toFixed(2)}°C, Pixels: ${temp2025.validPixels}`);

  // 5. Get max temperatures for June 2020-2024
  let maxTemp2020_2024 = -Infinity;
  let hasValidData = false;

  for (let year = 2020; year <= 2024; year++) {
    console.log(`\nGetting max temperature for June ${year}...`);
    const result = await getJuneMaxTemp(year);

    if (result.temp !== null) {
      hasValidData = true;
      console.log(`June ${year} Max Temp: ${result.temp.toFixed(2)}°C, Pixels: ${result.validPixels}`);
      if (result.temp > maxTemp2020_2024) {
        maxTemp2020_2024 = result.temp;
      }
    } else {
      if (result.validPixels === 0) {
        console.log(`C2: No valid pixels for June ${year}`);
        console.log("<answer>C2</answer>");
        return;
      } else {
        console.log(`C1: No data for June ${year}`);
        console.log("<answer>C1</answer>");
        return;
      }
    }
  }

  if (!hasValidData) {
    console.log("C1: No valid data for 2020-2024");
    console.log("<answer>C1</answer>");
    return;
  }

  // 6. Validate results
  if (temp2025.temp === undefined || temp2025.temp === null || 
      isNaN(temp2025.temp) || !isFinite(temp2025.temp) ||
      maxTemp2020_2024 === undefined || maxTemp2020_2024 === null || 
      isNaN(maxTemp2020_2024) || !isFinite(maxTemp2020_2024)) {
    console.log("C3: Invalid temperature values");
    console.log("<answer>C3</answer>");
    return;
  }

  // Check for unrealistic temperatures (outside -60 to 60°C range)
  if (temp2025.temp < -60 || temp2025.temp > 60 || 
      maxTemp2020_2024 < -60 || maxTemp2020_2024 > 60) {
    console.log("C3: Temperature outside valid range");
    console.log("<answer>C3</answer>");
    return;
  }

  // 7. Compare and output result
  console.log(`\nComparison:`);
  console.log(`2025-06-24 Temperature: ${temp2025.temp.toFixed(2)}°C`);
  console.log(`Max June Temp 2020-2024: ${maxTemp2020_2024.toFixed(2)}°C`);
  console.log(`Is 2025 temp higher? ${temp2025.temp > maxTemp2020_2024}`);

  if (temp2025.temp > maxTemp2020_2024) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
